    encoding: 'utf-8',
    timeout: 30_000,
    env: { ...cleanEnv, KSPEC_AUTHOR: '@test', ...env },
    input: stdin !== undefined ? (stdin.endsWith('\n') ? stdin : stdin + '\n') : undefined,
